package com.trustvault.user;
import com.trustvault.audit.AuditService; import com.trustvault.common.CurrentUser; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@Controller @RequestMapping("/employees") public class EmployeeController {
 private final AppUserRepository users;private final PasswordEncoder encoder;private final AuditService audit;private final CurrentUser current;
 public EmployeeController(AppUserRepository users,PasswordEncoder encoder,AuditService audit,CurrentUser current){this.users=users;this.encoder=encoder;this.audit=audit;this.current=current;}
 @GetMapping public String list(Model m){m.addAttribute("employees",users.findAllByOrderByFullNameAsc());return "admin/employees";}
 @GetMapping("/new") public String form(Model m){m.addAttribute("form",new EmployeeForm());m.addAttribute("roles",Role.values());return "admin/employee-form";}
 @PostMapping public String create(@Valid @ModelAttribute("form")EmployeeForm f,BindingResult r,Model m){if(users.existsByEmailIgnoreCase(f.email))r.rejectValue("email","duplicate","Email already exists");if(r.hasErrors()){m.addAttribute("roles",Role.values());return "admin/employee-form";}AppUser u=users.save(new AppUser(f.fullName,f.email,encoder.encode(f.password),f.role,f.department));audit.record(current.get().getEmail(),"EMPLOYEE_CREATED","SUCCESS",null,null,"Created employee "+u.getEmail());return "redirect:/employees?created";}
 @GetMapping("/{id}/edit") public String edit(@PathVariable UUID id,Model m){AppUser u=users.findById(id).orElseThrow();EmployeeEditForm f=new EmployeeEditForm();f.fullName=u.getFullName();f.email=u.getEmail();f.department=u.getDepartment();f.role=u.getRole();m.addAttribute("form",f);m.addAttribute("employee",u);m.addAttribute("roles",Role.values());return "admin/employee-edit";}
 @PostMapping("/{id}/edit") public String update(@PathVariable UUID id,@Valid @ModelAttribute("form")EmployeeEditForm f,BindingResult r,Model m){AppUser u=users.findById(id).orElseThrow();users.findByEmailIgnoreCase(f.email).filter(other->!other.getId().equals(id)).ifPresent(other->r.rejectValue("email","duplicate","Email already exists"));if(r.hasErrors()){m.addAttribute("employee",u);m.addAttribute("roles",Role.values());return "admin/employee-edit";}u.setFullName(f.fullName);u.setEmail(f.email);u.setDepartment(f.department);u.setRole(f.role);if(f.password!=null&&!f.password.isBlank()){if(f.password.length()<12){r.rejectValue("password","short","Password must be at least 12 characters");m.addAttribute("employee",u);m.addAttribute("roles",Role.values());return "admin/employee-edit";}u.setPasswordHash(encoder.encode(f.password));}users.save(u);audit.record(current.get().getEmail(),"EMPLOYEE_UPDATED","SUCCESS",null,null,"Updated employee "+u.getEmail());return "redirect:/employees?updated";}
 @PostMapping("/{id}/disable") public String disable(@PathVariable UUID id){AppUser u=users.findById(id).orElseThrow();if(u.getId().equals(current.get().getId()))throw new IllegalArgumentException("You cannot disable your own account");u.setEnabled(false);users.save(u);audit.record(current.get().getEmail(),"EMPLOYEE_DISABLED","SUCCESS",null,null,"Disabled employee "+u.getEmail());return "redirect:/employees?disabled";}
 public static class EmployeeEditForm { @NotBlank public String fullName; @Email @NotBlank public String email; public String password; @NotNull public Role role=Role.VIEWER; @NotBlank public String department; }
 public static class EmployeeForm { @NotBlank public String fullName; @Email @NotBlank public String email; @NotBlank @Size(min=12) public String password; @NotNull public Role role=Role.VIEWER; @NotBlank public String department; }
}
